import{_ as n,l as i,o as e,c as s,v as t,p as o,x as r,d,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Wanda","description":"","frontmatter":{"title":"Wanda","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/wanda.md","filePath":"llm/wanda.md","lastUpdated":1789023840000}'),h={name:"llm/wanda.md"};function c(E,a,A,m,u,P){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="wanda" tabindex="-1">Wanda <a class="header-anchor" href="#wanda" aria-label="Permalink to &quot;Wanda&quot;">​</a></h1><div class="epigraph"><p>不必解 Hessian：权重的幅度乘上校准激活的范数，已经能给 LLM 一张够用的剪枝分数。贵的是校准前向，不是二阶补偿。</p><footer>—— Sun, Liu, Bair, Kolter, A Simple and Effective Pruning Approach for Large Language Models, ICLR 2024</footer></div><p><a href="/llm/sparsegpt">上一课</a> 把 GPTQ 的二次重建改成置零，留下的非零被 squirt 过。本课丢掉补偿，只留打分。缺口是：<strong>一次性剪枝是否必须二阶。</strong> Wanda（pruning by Weights AND Activations）给出更便宜的是：\\(s_{ij}=|W_{ij}|\\cdot \\|X_j\\|_2\\)。后课 2:4 要的是分数能被 N:M 约束吃进去；本课先把无 Hessian 的基线立住。不重推 <a href="/llm/gptq">GPTQ</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SparseGPT 每层要形成 \\(XX^\\top\\)、做 Cholesky、按列补偿，175B 可跑，但实现重、对数值与块大小敏感。幅度剪枝 \\(|W|\\) 完全不要校准，却会误删「权小、激活大」的连接——<a href="/llm/unstructured-sparsity">非结构化稀疏</a> 已经警告过。缺口是中间物：用一次校准前向读 \\(\\|X\\|\\)，按元素乘到 \\(|W|\\) 上，组内比较后置零。没有牛顿步，留下的非零就是原值。</p><p>比较必须锁稀疏度、校准条数与是否允许重训。Wanda 论文的主张是：在中等稀疏、不重训时，与 SparseGPT 接近，墙钟低一个数量级。不要把这句话外推到 2:4 加速或 90% 稀疏。</p><p><span class="marginnote">比较在输出神经元内部做：每个 row 单独按分数排序置零，避免某一行被全局阈值删光。这是结构化程度极弱的「按行配额」，还不是通道剪枝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一层线性 \\(Y=WX\\)，用校准激活组成 \\(X\\)。对输入通道 \\(j\\) 计 \\(\\|X_j\\|_2\\)（或均值绝对值，实现可变），分数 \\(s_{ij}=|W_{ij}|\\,\\|X_j\\|_2\\)。每个输出通道保留分数最高的那一段，其余置零。无需迭代、无需更新留下的值。量化若还要做，应在剪完后用真实稀疏前向重校准，不能拿稠密 \\(X\\) 去跑 <a href="/llm/gptq">GPTQ</a>。</p>',9)),(e(),o(_,null,{default:r(()=>[p(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%A0%A1%E5%87%86%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20NX%5B%22%E9%80%9A%E9%81%93%E8%8C%83%E6%95%B0%22%5D%0A%20%20W%5B%22%E7%A8%A0%E5%AF%86%20W%22%5D%20--%3E%20S%5B%22%E5%88%86%E6%95%B0%20%7CW%7C%20*%20%7C%7CX%7C%7C%22%5D%0A%20%20NX%20--%3E%20S%0A%20%20S%20--%3E%20MASK%5B%22%E6%8C%89%E8%A1%8C%E9%85%8D%E9%A2%9D%E7%BD%AE%E9%9B%B6%22%5D%0A%20%20MASK%20--%3E%20SP%5B%22%E7%A8%80%E7%96%8F%20W%2C%20%E5%80%BC%E6%9C%AA%E8%A1%A5%E5%81%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 SparseGPT 的分工：要极高稀疏、或已经有 GPTQ 代码路径，用补偿；要快扫、要当 2:4 的打分器，用 Wanda。二者都不是 QAT。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(|w|\\,\\|x\\|\\) 是对 \\(|w x|\\) 的粗糙上界：激活长期大的通道，即使权重小也被保护。这与 AWQ 的「激活大则权重要更准」同一直觉，动作从改格子变成留连接。没有二阶，删掉的误差不会被邻居吸收，所以同一稀疏度下重建 MSE 通常差于 SparseGPT；下游是否可感，取决于该层误差是否被残差消化。</p><p>校准域同样决定谁被当成大激活。代码通道若没进校准，会被当成可删。签字纪律与量化退化课相同：分能力，不单看 PPL。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要期望 Wanda 的非结构掩码在 GPU 上加速。不要把「接近 SparseGPT」写成「替代 Hessian」。留下的值未被更新，不能把 Wanda 检查点当成 SparseGPT 的压缩版互相加载。下一课 2:4：把分数变成硬件认的模式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Wanda：一次性、按 \\(|W|\\cdot\\|X\\|\\) 打分，无 Hessian 补偿。</li><li>便宜的是二阶，不是校准；校准域仍决定掩码。</li><li>中等稀疏、不重训时是强基线；极端稀疏仍看 SparseGPT。</li><li>按行配额不等于结构化剪枝，也不等于有核。</li><li>出处：Sun et al., ICLR 2024。</li></ul>',8))])}const f=n(h,[["render",c]]);export{T as __pageData,f as default};
